{
  "status": "SUPPORTED",
  "task_summary": "Prepare the living room for two people to enjoy refreshments while watching television. Provide each person with their own refreshment setting nearby, and place the entertainment control where it is accessible to both people.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "REGION",
        "function": "A surface area designated to hold a complete refreshment set (cup and plate) for one person.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "coffee table surface",
          "side table surface",
          "console table surface",
          "desk surface",
          "any flat furniture surface"
        ],
        "required_properties": []
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "A device used to control the television.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "remote control",
          "media controller",
          "TV remote"
        ],
        "required_properties": []
      },
      {
        "id": "television",
        "entity_kind": "OBJECT",
        "function": "The display device being watched.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "television",
          "TV screen",
          "monitor"
        ],
        "required_properties": []
      }
    ],
    "functional_relations": [
      {
        "subject_role": "refreshment_setting",
        "relation": "must be located in proximity to",
        "object_role": "television",
        "required": true
      },
      {
        "subject_role": "entertainment_control",
        "relation": "must be placed within reach of",
        "object_role": "refreshment_setting",
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "op_1",
        "operation": "Place refreshment set on surface",
        "source_role": "refreshment_setting",
        "target_role": "refreshment_setting",
        "operation_count": 2,
        "reuse_policy": "REUSABLE_ACROSS_TARGETS",
        "anchor_role": "refreshment_setting"
      },
      {
        "id": "op_2",
        "operation": "Move entertainment control to accessible location",
        "source_role": "entertainment_control",
        "target_role": "refreshment_setting",
        "operation_count": 1,
        "reuse_policy": "DEDICATED_PER_TARGET",
        "anchor_role": "refreshment_setting"
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_setting": [
        {
          "label": "coffee_table",
          "visual_description": "A low rectangular table with a light green top located centrally between the two armchairs."
        },
        {
          "label": "side_table_left",
          "visual_description": "A small wooden side table located to the left of the left armchair."
        },
        {
          "label": "side_table_right",
          "visual_description": "A small wooden side table located to the right of the right armchair."
        },
        {
          "label": "console_table",
          "visual_description": "A long wooden table located against the back wall under the television."
        },
        {
          "label": "desk",
          "visual_description": "A large wooden desk located in the foreground."
        }
      ],
      "entertainment_control": [
        {
          "label": "remote_control",
          "visual_description": "A black remote control currently resting on the large wooden desk."
        }
      ],
      "television": [
        {
          "label": "television",
          "visual_description": "A black flat-screen television mounted on the back wall."
        }
      ]
    },
    "inspectable_regions": [],
    "inspection_order": []
  }
  ,
  "unsupported_reason": ""
}
